-- 0004_execution_pod_login — the login every executor pod connects as.
--
-- GENERATED by publish/extract_leg_grants.py from the live grants of the
-- database the schema was dumped from, each table cross-checked against a
-- source migration. Do not edit by hand; regenerate.
--
-- WHY A MIGRATION AND NOT `google_sql_user`. A Cloud SQL user created
-- through the API is a member of cloudsqlsuperuser, which can create roles
-- and databases -- more than the application holds. The pod's login is the
-- narrowest identity in the system, so it is a plain role holding exactly
-- the grants below and nothing inherited. Its PASSWORD is not here:
-- terraform generates it into the `execution-db-password` secret and
-- migrations/_access.py sets it on every migrate run, so the two cannot
-- drift.
--
-- NO DEFAULT PRIVILEGES, on purpose: a table a later migration adds is
-- invisible to pods until that migration grants it.

DO $LEG$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'agentos_leg') THEN
        CREATE ROLE agentos_leg LOGIN CONNECTION LIMIT 80;
    END IF;
END
$LEG$;

GRANT USAGE ON SCHEMA kernel TO agentos_leg;
GRANT USAGE ON SCHEMA public TO agentos_leg;

-- Tables
GRANT INSERT, SELECT, UPDATE ON kernel.answers TO agentos_leg;
