-- The database itself. Only the three logins may open it; PUBLIC may not,
-- so another database's users on this instance cannot. Revoking needs the
-- owner's rights, which the migrate login holds as a member of the owning
-- role on Cloud SQL. Without them this WARNS instead of failing a run whose
-- grants above all applied -- and preflight reports the open door by name.
DO $DB$
DECLARE login text;
BEGIN
    FOREACH login IN ARRAY ARRAY['agentos_leg', 'app_user', 'migrate_user']
    LOOP
        IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = login) THEN
            EXECUTE format('GRANT CONNECT ON DATABASE %I TO %I', current_database(), login);
        END IF;
    END LOOP;
    IF pg_has_role(current_user,
                   (SELECT datdba FROM pg_database WHERE datname = current_database()),
                   'USAGE') THEN
        EXECUTE format('REVOKE CONNECT ON DATABASE %I FROM PUBLIC', current_database());
    ELSE
        RAISE WARNING '% does not own %, so PUBLIC keeps CONNECT',
                      current_user, current_database();
    END IF;
END
$DB$;
